/* plugin: libcsv.so */
static const plugin_vtable VT = { .abi_version = 2, .name = "csv", .format = csv_format };
const plugin_vtable *plugin_entry(void) { return &VT; }

/* host */
void *h = dlopen("./plugins/libcsv.so", RTLD_NOW | RTLD_LOCAL);
if (!h) { fprintf(stderr, "%s\n", dlerror()); return -1; }
const plugin_vtable *(*entry)(void) = dlsym(h, "plugin_entry");
const plugin_vtable *p = entry();
if (p->abi_version != 2) { dlclose(h); return -1; }
